ed":true,"fields":[{"key":"produtos","type":"list","required":true},{"key":"marcas","type":"list"},{"key":"exclusividades","type":"list"}]},{"key":"comercial","label":"Condições comerciais","required":true,"fields":[{"key":"pedido_minimo","type":"money_range","required":true},{"key":"prazo_pagamento","type":"text","required":true},{"key":"politica_desconto","type":"text"},{"key":"tabela_por_volume","type":"boolean"}]},{"key":"logistica","label":"Entrega","required":true,"fields":[{"key":"regiao_atendida","type":"text","required":true},{"key":"prazo_entrega","type":"text","required":true},{"key":"frete","type":"text"},{"key":"dias_de_rota","type":"text"}]},{"key":"diferencial","label":"Diferencial","fields":[{"key":"motivo_trocar","type":"text","required":true},{"key":"suporte","type":"text"}]}],"categories":{"pricing":"Tabela, pedido mínimo e desconto por volume","risk_free_entry":"Pedido de entrada reduzido para experimentar","availability":"Estoque, prazo de entrega e dias de rota","expertise_proof":"Tempo de mercado, marcas e clientes atendidos","catalog":"Linhas, marcas e exclusividades","goal_matching":"Perfil do estabelecimento → mix ideal","objections":"Caro, já tenho fornecedor, pedido mínimo alto","commitment_offer":"Contrato de fornecimento e condição por volume","reciprocity":"Amostra, brinde e apoio de ponto de venda","limits_and_ethics":"O que não prometer sobre preço, prazo e frete","retention":"Recompra, reposição e cliente inativo","ecosystem":"Representantes, transportadoras e indústria parceira"},"cadences":[{"key":"pos_cotacao","applies_to":"proposal_followup","steps":[{"offset_days":2,"intent":"Confirmar recebimento e tirar dúvida"},{"offset_days":6,"intent":"Oferecer condição de entrada"}],"stop_on":["replied","converted","opted_out","lost"]},{"key":"recompra","applies_to":"repurchase","steps":[{"offset_days":25,"intent":"Antecipar a reposição antes de acabar o estoque"}],"stop_on":["converted","opted_out"]},{"key":"reativacao","applies_to":"reactivation","steps":[{"offset_days":45,"intent":"Descobrir por que parou de comprar"}],"stop_on":["replied","converted","opted_out"],"max_attempts":3}],"hard_rules":["Nunca prometer preço, prazo ou frete fora do que está no DNA.","Não desqualificar o fornecedor atual do cliente — mostrar a vantagem, não atacar."],"kpis":["taxa_conversao","ticket_medio","recompra","clientes_ativos","tempo_resposta_mediana"]}'::jsonb, 'published', now())
