-- ---------------------------------------------------------------------
-- capabilities nos segmentos B2C ja existentes.
-- capabilities decide quais ABAS de modulo aparecem no painel. B2C local
-- nao faz prospeccao fria de pessoas (LGPD) — por isso lista vazia.
-- ---------------------------------------------------------------------
update public.skills
   set manifest = jsonb_set(manifest, '{capabilities}', '[]'::jsonb)
 where key in ('academia','barbearia')
   and not (manifest ? 'capabilities');
